#include "gemm.cuh"
#include <cuda_runtime.h>

#define BLOCK_SIZE 16
#define REG_TILE_M 8
#define REG_TILE_N 8
#define K_TILE 16

#define TILE_M (BLOCK_SIZE * REG_TILE_M)
#define TILE_N (BLOCK_SIZE * REG_TILE_N)

__global__ void gemmKernel(const float* A, const float* B, float* C, int N) {
    __shared__ float As[K_TILE][TILE_M];
    __shared__ float Bs[K_TILE][TILE_N];

    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int tid = ty * BLOCK_SIZE + tx;

    float acc[REG_TILE_M][REG_TILE_N] = {0.0f};

    for (int t = 0; t < (N + K_TILE - 1) / K_TILE; ++t) {
        // Load As: TILE_M x K_TILE (128 x 16)
        // Total 2048 elements. 256 threads -> 8 elements per thread.
        // We want to load As[k][m] where k is 0..15 and m is 0..127.
        // Coalesced load: load 4 elements from the same row of A.
        // Each thread loads 2 float4s.
        for (int i = 0; i < 2; ++i) {
            int load_id = tid + i * 256;
            // We have 128 rows and 16 cols in the tile.
            // We can treat this as 128 rows of 4-float blocks.
            // Total float4s = 128 * (16/4) = 512.
            // Each thread loads 2.
            int row = load_id / 4; // 0 to 511 / 4 = 127
            int col_block = load_id % 4; // 0 to 3
            int col = col_block * 4;

            int global_row = blockIdx.y * TILE_M + row;
            int global_col = t * K_TILE + col;

