            int global_row = blockIdx.y * TILE_M + row;
            int global_col = t * K_TILE + col;

            if (global_row < N && global_col < N) {
                if (N % 4 == 0 && (global_col + 3) < N) {
                    float4 val = reinterpret_cast<const float4*>(A + global_row * N + global_col)[0];
                    As[col][row] = val.x;
                    As[col + 1][row] = val.y;
                    As[col + 2][row] = val.z;
                    As[col + 3][row] = val.w;
                } else {
                    for (int k = 0; k < 4; ++k) {
                        int gc = global_col + k;
                        if (global_row < N && gc < N) As[col + k][row] = A[global_row * N + gc];
                        else As[col + k][row] = 0.0f;
                    }
                }
            } else {
                for (int k = 0; k < 4; ++k) {
                    int gc = global_col + k;
                    if (global_row < N && gc < N) As[col + k][row] = A[global_row * N + gc];
                    else As[col + k][row] = 0.0f;
                }
            }
        }

        // Load Bs: K_TILE x TILE_N (32 x 128)
        for (int i = 0; i < 4; ++i) {
            int load_id = tid + i * 256;
