#define TILE_M (BLOCK_SIZE * REG_TILE_M)
#define TILE_N (BLOCK_SIZE * REG_TILE_N)

__global__ void gemmKernel(const float* A, const float* B, float* C, int N) {
    __shared__ float As[K_TILE][TILE_M + 1];
    __shared__ float Bs[K_TILE][TILE_N + 1];

    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int tid = ty * BLOCK_SIZE + tx;

    float acc[REG_TILE_M][REG_TILE_N];
    #pragma unroll
    for (int m = 0; m < REG_TILE_M; ++m) {
        #pragma unroll
        for (int n = 0; n < REG_TILE_N; ++n) {
            acc[m][n] = 0.0f;
        }
    }

    for (int t = 0; t < (N + K_TILE - 1) / K_TILE; ++t) {
        for (int i = 0; i < 4; ++i) {
            int load_id = tid + i * 256;
            int row = load_id / 8;
            int col_block = load_id % 8;
            int col = col_block * 4;
            int global_row = blockIdx.y * TILE_M + row;
            int global_col = t * K_TILE + col;
            if (global_row < N && global_col < N) {
                if (N % 4 == 0 && (global_col + 3) < N) {
                    float4 val = reinterpret_cast<const float4*>(A + global_row * N + global_col)[0];
                    As[col][row] = val.x;
                    As[col + 1][row] = val.y;
                    As[col + 2][row] = val.z;
                    As[col + 3][row] = val.w;
                } else {
                    for (int k = 0; k < 4; ++k) {
                        int gc = global_col + k;
                        if (global_row < N && gc < N) As[col + k][row] = A[global_row * N + gc];
                        else As[col + k][row] = 0.0f;
                    }
                }
            } else {
                for (int k = 0; k < 4; ++k) {
                    int gc = global_col + k;
                    if (global_row < N && gc < N) As[col + k][row] = A[global_row * N + gc];
                    else As[col + k][row] = 0.0f;
                }
            }
        }
        for (int i = 0; i < 4; ++i) {
            int load_id = tid + i * 256;
            int row = load_id / 32;
            int col_block = load_id % 32;
            int col = col_block * 4;
            int global_row = t * K_TILE + row;
            int global_col = blockIdx.x * TILE_N + col;
            if (global_row < N && global_col < N) {
                if (N % 4 == 0 && (global_col + 3) < N) {
                    float4 val = reinterpret_cast<const float4*>(B + global_row * N + global_col)[0];
                    Bs[row][col] = val.x;
                    Bs[row][col + 1] = val.y;
                    Bs[row][col + 2] = val.z;
                    Bs[row][col + 3] = val.w;
                } else {
                    for (int k = 0; k < 4; ++k) {
                        int gc = global_col + k;
                        if (global_row < N && gc < N) Bs[row][col + k] = B[global_row * N + gc];
                        else Bs[row][col + k] = 0.0f;
                    }
                }
            } else {
                for (int k = 0; k < 4; ++k) {
                    int gc = global_col + k;
                    if (global_row < N && gc < N) Bs[row][col + k] = B[global_row * N + gc];
                    else Bs[row][col + k] = 0.0f;
                }
            }
        }
        __syncthreads();
        #pragma unroll
        for (int k = 0; k < K_TILE; ++k) {
            #pragma unroll
            for (int m = 0; m < REG_TILE_M; ++m) {
                float a_val = As[k][ty * REG_TILE_M + m];
                #pragma unroll
                for (int n = 0; n < REG_TILE_N; ++n) {
                    acc[m][n] += a_val * Bs[k][tx * REG_TILE_N + n];
                }
            }
        }
        __syncthreads();
    }
    int row_start = blockIdx.y * TILE_M + ty * REG_TILE_M;
    int col_start = blockIdx.x * TILE_N + tx * REG_TILE_N;
    for (int m = 0; m < REG_TILE_M; ++m) {
        for (int n = 0; n < REG_TILE_N; ++n) {
            int row = row_start + m;
            int col = col_start + n;
            if (row < N && col < N) {
                C[row * N + col] = acc[m][n];
            }
        }
    }
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    dim3 block(BLOCK_SIZE, BLOCK_SIZE);
    dim3 grid((N + TILE_M - 1) / TILE_M, (N + TILE_N - 1) / TILE_N);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}
